import json

def rotate_90(g):
    return [[g[4-c][r] for c in range(5)] for r in range(5)]

TL = [[3, 3, 1, 3, 3], [6, 3, 3, 5, 6], [1, 5, 3, 3, 3], [5, 3, 6, 3, 0], [3, 3, 5, 3, 3]]
r90 = rotate_90(TL)
r180 = rotate_90(r90)

grid = [[0]*11 for _ in range(11)]
for r in range(11):
    for c in range(11):
        if r == 5 or c == 5:
            grid[r][c] = 4  # cross

    # TL: 0-4, 0-4
    if r < 5 and c < 5:
        grid[r][c] = TL[r][c]
    # TR: 0-4, 6-10
    if r < 5 and c >= 6:
        grid[r][c] = TL[r][c-6]
    # BL: 6-10, 0-4
    if r >= 6 and c < 5:
        grid[r][c] = TL[r-6][c]
    # BR: 6-10, 6-10
    if r >= 6 and c >= 6:
        grid[r][c] = r180[r-6][c-6]

print("Grid with BR=180CW of TL:")
for row in grid:
    print(row)

result = json.dumps({"action": "submit", "grid": grid})
print(result)

